// Package seedcheck verifies that the benchmark database was seeded as db/seed.sql defines.
package seedcheck

import (
	"context"
	"database/sql"
	"fmt"
	"slices"
	"strconv"
	"strings"

	_ "github.com/jackc/pgx/v5/stdlib"
)

// WantPostgresMajor is the Postgres major version the benchmark targets.
const WantPostgresMajor = 15

// postgresVersionNumMultiple converts server_version_num (e.g. 150013) to a major version.
const postgresVersionNumMultiple = 10000

// ExpectedRows mirrors the row counts generated by db/seed.sql.
var ExpectedRows = map[string]int64{
	"models":    10000,
	"customers": 1000,
	"suppliers": 1000,
	"orders":    10000,
}

// diffCounts returns one sorted message per table whose count differs or is missing.
func diffCounts(want, got map[string]int64) []string {
	var diffs []string
	for table, wantCount := range want {
		gotCount, ok := got[table]
		switch {
		case !ok:
			diffs = append(diffs, fmt.Sprintf("%s: missing", table))
		case gotCount != wantCount:
			diffs = append(diffs, fmt.Sprintf("%s: want %d, got %d", table, wantCount, gotCount))
		}
	}
	slices.Sort(diffs)
	return diffs
}

// Check verifies the Postgres major version and every table's row count.
func Check(ctx context.Context, db *sql.DB) error {
	var versionNum string
	if err := db.QueryRowContext(ctx, "SHOW server_version_num").Scan(&versionNum); err != nil {
		return fmt.Errorf("seedcheck: read server version: %w", err)
	}
	num, err := strconv.Atoi(versionNum)
	if err != nil {
		return fmt.Errorf("seedcheck: parse server_version_num %q: %w", versionNum, err)
	}
	if major := num / postgresVersionNumMultiple; major != WantPostgresMajor {
		return fmt.Errorf("seedcheck: postgres major %d, want %d", major, WantPostgresMajor)
	}

	got := make(map[string]int64, len(ExpectedRows))
	for table := range ExpectedRows {
		var count int64
		// Table names come from the ExpectedRows constant above, never from input.
		query := "SELECT count(*) FROM " + table
		if err := db.QueryRowContext(ctx, query).Scan(&count); err != nil {
			return fmt.Errorf("seedcheck: count %s: %w", table, err)
		}
		got[table] = count
	}
	if diffs := diffCounts(ExpectedRows, got); len(diffs) > 0 {
		return fmt.Errorf("seedcheck: seed drift: %s", strings.Join(diffs, "; "))
	}
	return nil
}
